<script setup>
import {ref,reactive,onMounted,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,notifyError} from '../lib/api.js'
import {typeName,categoryTone} from '../lib/format.js'
import StateBox from '../components/StateBox.vue'
import AppIcon from '../components/AppIcon.vue'
const list=ref([]),loading=ref(false),error=ref(''),dialog=ref(false),busy=ref(false),editing=ref(null),formRef=ref(),form=reactive({name:'',type:'EXPENSE'})
const personal=computed(()=>list.value.filter(c=>c.userId!==null)),defaults=computed(()=>list.value.filter(c=>c.userId===null))
const rules={name:[{required:true,whitespace:true,message:'请输入分类名称',trigger:'blur'},{max:30,message:'名称最多30字',trigger:'blur'}]}
async function load(){loading.value=true;error.value='';try{list.value=await api.get('/categories')}catch(e){error.value=e.message}finally{loading.value=false}}
function open(c=null){editing.value=c;Object.assign(form,{name:c?.name||'',type:c?.type||'EXPENSE'});dialog.value=true;formRef.value?.clearValidate()}
async function save(){if(busy.value||!await formRef.value.validate().catch(()=>false))return;busy.value=true;try{const payload={name:form.name.trim(),type:form.type};if(editing.value)await api.put(`/categories/${editing.value.id}`,payload);else await api.post('/categories',payload);dialog.value=false;ElMessage.success('分类已保存');await load()}catch(e){notifyError(e)}finally{busy.value=false}}
async function remove(c){try{await ElMessageBox.confirm(`删除“${c.name}”？已关联账单的分类需要先调整账单。`,'删除分类',{confirmButtonText:'确认删除',cancelButtonText:'取消',type:'warning'})}catch{return}try{await api.delete(`/categories/${c.id}`);ElMessage.success('分类已删除');await load()}catch(e){notifyError(e)}}
onMounted(load)
</script><template><div v-loading="loading"><StateBox :error="error" @retry="load"><section class="panel"><div class="panel-heading"><div><h2>我的分类</h2><p>按你的生活习惯，补充专属类别</p></div><el-button type="primary" plain @click="open()"><AppIcon name="Plus" :size="16"/>新建分类</el-button></div><StateBox :empty="!personal.length" title="还没有自定义分类" description="默认分类已准备好，也可以添加学习、旅行等专属类别。"/><div v-if="personal.length" class="category-grid"><article v-for="c in personal" :key="c.id" class="category-card"><span class="category-icon" :class="categoryTone(c.name)"><AppIcon name="CollectionTag"/></span><div><h3>{{c.name}}</h3><p>{{typeName(c.type)}} · 自定义</p></div><div class="category-actions"><el-button link type="primary" @click="open(c)">编辑</el-button><el-button link type="danger" @click="remove(c)">删除</el-button></div></article></div></section><section class="panel mt"><div class="panel-heading"><div><h2>默认分类</h2><p>系统预设，所有用户均可使用</p></div><span class="subtle-label"><AppIcon name="Lock" :size="14"/>不可编辑</span></div><div class="category-grid"><article v-for="c in defaults" :key="c.id" class="category-card"><span class="category-icon" :class="categoryTone(c.name)"><AppIcon :name="c.type==='INCOME'?'TopRight':'CollectionTag'"/></span><div><h3>{{c.name}}</h3><p>{{typeName(c.type)}}</p></div></article></div></section></StateBox></div><el-dialog v-model="dialog" :title="editing?'编辑分类':'新建分类'" width="430px" :close-on-click-modal="false"><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="save"><el-form-item label="分类名称" prop="name"><el-input v-model="form.name" maxlength="30" placeholder="例如：学习资料"/></el-form-item><el-form-item label="收支类型"><el-radio-group v-model="form.type"><el-radio-button value="EXPENSE">支出</el-radio-button><el-radio-button value="INCOME">收入</el-radio-button></el-radio-group></el-form-item><p class="small muted">已有账单使用的分类不能变更收支类型。</p><div class="dialog-footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存分类</el-button></div></el-form></el-dialog></template>
